accept_promotion_mutation#a386a03946feee:
mutation AcceptPromotion($urn: URN!, $amount: Float) {
  acceptPromotion(urn: $urn, amount: $amount) {
    responseCode
    responseMessage
    promotion {
      ...imsPromotion
    }
  }
}

fragment imsPromotion on ImsPromotion {
  urn
  headline
  subHeadline
  bonusInstanceCode
  ctaText
  layout
  status
  timeLeft
  wagerType
  percentCompleted
  bonusWagering
  wageringLeft
  bonusAwarded
  currentBonusBalance
  amountOnPendingWinnings
  freeSpins {
    initialFreeSpins
    remainingFreeSpins
  }
  goldenChips {
    initialGoldenChips
    remainingGoldenChips
    goldenChipsAmount
  }
  buyIn {
    buyInMinValue
    buyInMaxValue
    boughtIn
    intervals {
      min
      max
      amount
      percentage
    }
  }
  image {
    url
    alt
    dimensions {
      width
      height
    }
  }
}

betting_card_runners_display_query#8202c:
query BettingCardRunnersDisplay($urn: [URN!]!, $requestForExc: Boolean!, $requestForSbk: Boolean!, $preferences: LayoutPreferencesInput, $productExclusions: [ProductExclusion!]) @preferences(preferences: $preferences) @productExclusions(productExclusions: $productExclusions) {
  Cards(cardsURN: $urn) {
    __typename
    ... on MarketCard {
      urn
      displayRunners {
        ...displayRunners
      }
    }
    ... on MarketExtendedCard {
      urn
      displayRunners {
        ...displayRunners
      }
    }
    ... on EventMarketCard {
      urn
      displayRunners {
        ...displayRunners
      }
    }
    ... on RaceMarketCard {
      urn
      displayRunners {
        ...displayRunners
      }
    }
  }
}

fragment displayRunners on DisplayRunners {
  exchange @include(if: $requestForExc) {
    runners {
      runnerURN
    }
  }
  sportsbook @include(if: $requestForSbk) {
    runners {
      runnerURN
    }
  }
}

