main_markets_query#2cc96fde7cd4d09f44a02:
query MainMarkets($urn: [URN!]!, $withFixtureUpdates: Boolean!, $preferences: LayoutPreferencesInput, $productExclusions: [ProductExclusion!], $experiments: [ExperimentsInput!]) @preferences(preferences: $preferences) @productExclusions(productExclusions: $productExclusions) @experiments(experiments: $experiments) {
  Cards(cardsURN: $urn) {
    __typename
    ... on EventMarketCard {
      ...eventMarketCardWithoutSporeventOrFixture
      fixture @include(if: $withFixtureUpdates) {
        ...fixture
      }
    }
    ... on FixtureCard @include(if: $withFixtureUpdates) {
      urn
      fixture {
        ...fixture
      }
    }
  }
}

